        fun forTheme(mode: ThemeMode): DesktopThemePalette = when (mode) {
            ThemeMode.DARK -> dark
            ThemeMode.LIGHT -> light
            ThemeMode.SUNRISE -> sunrise
            ThemeMode.RED_DARK -> redDark
            ThemeMode.PURPLE_HAZE -> purpleHaze
            ThemeMode.ABYSS -> abyssDark
            ThemeMode.SUNSET -> sunset
            ThemeMode.CISHER -> cisher
            ThemeMode.BERRYNADE -> berrynade
            ThemeMode.SYSTEM -> error("Resolve System appearance before selecting a palette")
        }
    }
